<script setup>
import {Head,Link,useForm} from '@inertiajs/vue3';import CustomerShell from '../../Components/CustomerShell.vue';const props=defineProps({email:String,token:String});const form=useForm({email:props.email??'',token:props.token??'',password:'',password_confirmation:''});const submit=()=>{if(form.processing)return;form.post('/reset-password',{onFinish:()=>form.reset('password','password_confirmation')})};
</script><template><Head title="Kata sandi baru"/><CustomerShell compact-footer><main class="lf-auth-wrap"><form class="lf-auth-card" @submit.prevent="submit"><p class="lf-eyebrow">Keamanan akun</p><h1>Kata sandi baru</h1><p>Gunakan minimal 12 karakter.</p><div class="grid gap-3"><label class="text-[10px] font-semibold text-white/70">Email<input v-model="form.email" type="email" name="email" autocomplete="username" placeholder="Masukkan email akun" :aria-invalid="Boolean(form.errors.email)" required><span v-if="form.errors.email" role="alert" class="mt-1 block text-xs text-red-300">{{form.errors.email}}</span></label><label class="text-[10px] font-semibold text-white/70">Kata sandi baru<input v-model="form.password" type="password" name="password" autocomplete="new-password" placeholder="Minimal 12 karakter" :aria-invalid="Boolean(form.errors.password)" minlength="12" required><span v-if="form.errors.password" role="alert" class="mt-1 block text-xs text-red-300">{{form.errors.password}}</span></label><label class="text-[10px] font-semibold text-white/70">Ulangi kata sandi<input v-model="form.password_confirmation" type="password" name="password_confirmation" autocomplete="new-password" placeholder="Masukkan ulang kata sandi" :aria-invalid="Boolean(form.errors.password_confirmation)" required><span v-if="form.errors.password_confirmation" role="alert" class="mt-1 block text-xs text-red-300">{{form.errors.password_confirmation}}</span></label><p v-if="form.errors.token" role="alert" class="text-xs text-red-300">{{form.errors.token}}</p><button type="submit" class="lf-primary w-full" :disabled="form.processing">{{form.processing?'Menyimpan…':'Simpan kata sandi'}}</button></div><div class="lf-auth-links"><Link href="/forgot-password">Minta tautan baru</Link><Link href="/login">Kembali ke masuk</Link></div></form></main></CustomerShell></template>